package de.teamlapen.vampirism.annotation;

import java.lang.annotation.ElementType;
import java.lang.annotation.Repeatable;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Generates an abstract {@code Converted&lt;Name&gt;} base class for the given vanilla creature and wires up
 * its registration + usages.
 * <p>
 * For every annotation the processor emits:
 * <ul>
 *     <li>an abstract {@code Converted&lt;Name&gt;} base (extends the creature, implements
 *     {@code CurableConvertedCreature}, all common boilerplate). When {@link #subclass()} is unset it also
 *     carries the {@code getAttributeBuilder()} / {@code checkSpawnRules(...)} statics; when a subclass is
 *     given those live in the handwritten subclass instead.</li>
 *     <li>an entry in the generated {@code GeneratedConvertedEntities} registrar (DeferredHolder +
 *     attribute + spawn-placement registration + the {@code ALL} datagen descriptor list).</li>
 * </ul>
 * Place it on any holder type; it is {@link Repeatable}:
 * <pre>{@code
 * @ConvertedCreature(value = Cow.class, width = 0.9F, height = 1.4F)
 * @ConvertedCreature(value = Horse.class, width = 1.39F, height = 1.6F,
 *                    subclass = ConvertedHorseEntity.class, overlay = "horse")
 * public final class GeneratedConvertedCreatures {}
 * }</pre>
 */
@Target(ElementType.TYPE)
@Retention(RetentionPolicy.SOURCE)
@Repeatable(ConvertedCreatures.class)
public @interface ConvertedCreature {

    /**
     * The vanilla creature to convert, e.g. {@code Cow.class}. The generated base extends this type.
     */
    Class<?> value();

    /**
     * Registry id, e.g. {@code "converted_cow"}. Defaults to {@code "converted_" + lower(simpleName)}.
     * The registrar field name is this value upper-cased (e.g. {@code CONVERTED_COW}).
     */
    String registryName() default "";

    /**
     * The {@code net.minecraft.world.entity.EntityType} constant name used for curing / naming,
     * e.g. {@code "COW"}. Defaults to the upper-cased simple name of {@link #value()}.
     */
    String entityType() default "";

    /**
     * Overrides the generated base' simple name. Defaults to {@code "Converted" + simpleName(value())}.
     */
    String className() default "";

    /**
     * Optional handwritten concrete subclass (kept in the normal source set) used as the registered
     * entity. When set, the registration factory is {@code Subclass::new} and the subclass must provide
     * the {@code getAttributeBuilder()} / {@code checkSpawnRules(...)} statics. When unset, the abstract
     * base is registered via an anonymous subclass and carries those statics itself.
     */
    Class<?> subclass() default void.class;

    /**
     * Vanilla {@code EntityRenderer} class for client-side registration, e.g. {@code CowRenderer.class}.
     * The generated {@code GeneratedConvertedEntitiesClient} wraps it with the converted-overlay layer.
     * When unset ({@code void.class}) no client entry is generated for this creature.
     * Renderers needing extra constructor arguments (e.g. {@code DonkeyRenderer}) stay handwritten.
     */
    Class<?> renderer() default void.class;

    /**
     * Overlay texture key used for the vanilla&rarr;converted data map
     * ({@code textures/entity/vanilla/&lt;overlay&gt;_overlay.png}). Defaults to {@code lower(simpleName)}.
     */
    String overlay() default "";

    /**
     * Hitbox width passed to {@code EntityType.Builder.sized(width, height)}.
     * When {@code -1} (the default), {@code EntityType.<name>.getDimensions().width()} is used instead.
     */
    float width() default -1f;

    /**
     * Hitbox height passed to {@code EntityType.Builder.sized(width, height)}.
     * When {@code -1} (the default), {@code EntityType.<name>.getDimensions().height()} is used instead
     * and {@code EntityType.<name>.getDimensions().eyeHeight()} is also applied.
     */
    float height() default -1f;

    /** {@code net.minecraft.world.entity.MobCategory} constant name. Defaults to {@code "CREATURE"}. */
    String mobCategory() default "CREATURE";

    /**
     * Static method on the vanilla class used to build the attribute set, e.g. {@code "createAttributes"} or
     * {@code "createBaseHorseAttributes"}. The generated {@code getAttributeBuilder()} calls
     * {@code <VanillaClass>.<attributeMethod>().add(ATTACK_DAMAGE, ...).add(SUNDAMAGE, ...)}.
     */
    String attributeMethod() default "createAttributes";

    /**
     * Static spawn-rule method on the base type used by the generated {@code checkSpawnRules}, e.g.
     * {@code "checkGoatSpawnRules"}. Defaults to {@code "checkAnimalSpawnRules"}. Only consulted when
     * {@link #subclass()} is unset (otherwise the subclass owns the spawn rule).
     */
    String spawnRulesFrom() default "checkAnimalSpawnRules";

    /** Adds {@code .immuneTo(Blocks.SWEET_BERRY_BUSH)} to the entity-type builder (vanilla fox quirk). */
    boolean immuneToSweetBerryBush() default false;
}

package de.teamlapen.vampirism.api.world.entity.convertible;

import de.teamlapen.vampirism.api.VampirismApi;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntitySpawnReason;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.world.level.storage.TagValueOutput;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Optional;
import java.util.UUID;

/**
 * Enables the option to cure a {@link IConvertedCreature}
 * <p>
 * to implement this feature there are some requirements:<p>
 * - override {@link #startConverting} to save the conversion started and conversion time <p>
 * - create a {@link EntityDataAccessor<Boolean> } the is returned by {@link #getConvertingDataParam()}<p>
 * - call {@link #registerConvertingData(PathfinderMob)} in {@link net.minecraft.world.entity.Mob#registerData()}<p>
 * - call {@link #interactWithCureItem(Player, ItemStack, PathfinderMob)} in {@link net.minecraft.world.entity.Mob#mobInteract(Player, InteractionHand)} if the cure item is in the players hand<p>
 * - call {@link #handleSound(byte, PathfinderMob)} in {@link net.minecraft.world.entity.Mob#handleEntityEvent(byte)}<p>
 * - check in {@link net.minecraft.world.entity.Mob#aiStep()} if the conversion timer has ended. If so call {@link #cureEntity(ServerLevel, PathfinderMob, EntityType)} <p>
 */
@SuppressWarnings("JavadocReference")
public interface ICurableConvertedCreature<T extends PathfinderMob> extends IConvertedCreature<T> {

    byte CURE_EVENT_ID = (byte) 40;

    /**
     * creates the new entity <p>
     * <p>
     * override to use already an already existing entity
     *
     * @param entity  the entity that extends this interface
     * @param newType the entity type of the cured entity
     * @return the new entity
     */
    default T createCuredEntity(@NotNull PathfinderMob entity) {
        T newEntity = getCuredEntityType().create(entity.level(), EntitySpawnReason.CONVERSION);
        assert newEntity != null;
        TagValueOutput output = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, entity.registryAccess());
        entity.saveWithoutId(output);
        newEntity.load(TagValueInput.create(ProblemReporter.DISCARDING, entity.registryAccess(), output.buildResult()));
        newEntity.yBodyRot = entity.yBodyRot;
        newEntity.yHeadRot = entity.yHeadRot;
        newEntity.setUUID(UUID.randomUUID());
        return newEntity;
    }

    /**
     * @return The entity type this creature is cured to
     */
    @NotNull
    EntityType<T> getCuredEntityType();

    /**
     * creates the cured entity and copies attributes <p>
     * adds/removes the entities to/from the world <p>
     * <p>
     * override to copy additionally attributes
     *
     * @param world   the world of the curing process
     * @param entity  the entity that extends this interface
     * @param newType the entity type of the cured entity
     * @return the new cured entity
     */
    default T cureEntity(@NotNull ServerLevel world, @NotNull PathfinderMob entity) {
        T newEntity = createCuredEntity(entity);
        entity.remove(Entity.RemovalReason.DISCARDED);
        entity.level().addFreshEntity(newEntity);
        newEntity.addEffect(new MobEffectInstance(MobEffects.NAUSEA, 200, 0));
        if (!entity.isSilent()) {
            world.levelEvent(null, 1027, entity.blockPosition(), 0);
        }
        VampirismApi.extendedCreatureVampirism(newEntity).setBlood(1);
        net.neoforged.neoforge.event.EventHooks.onLivingConvert(entity, newEntity);
        return newEntity;
    }

    @NotNull
    EntityDataAccessor<Boolean> getConvertingDataParam();

    /**
     * call in {@link Entity#handleEntityEvent(byte)}
     *
     * @param id     the status id
     * @param entity the entity that extends this interface
     * @return if the staus update was handled
     */
    default boolean handleSound(byte id, @NotNull PathfinderMob entity) {
        if (id == CURE_EVENT_ID) {
            if (!entity.isSilent()) {
                entity.level().playLocalSound(entity.getX(), entity.getEyeY(), entity.getZ(), SoundEvents.ZOMBIE_VILLAGER_CURE, entity.getSoundSource(), 1.0F + entity.getRandom().nextFloat(), entity.getRandom().nextFloat() * 0.7F + 0.3F, false);
            }
            return true;
        }
        return false;
    }

    /**
     * call in {@link net.minecraft.world.entity.Mob#mobInteract(Player, InteractionHand)}
     *
     * @param player the interacting player
     * @param stack  the itemstack in the players hand
     * @param entity the entity that extends this interface
     * @return the action result
     */
    default @NotNull InteractionResult interactWithCureItem(@NotNull Player player, @NotNull ItemStack stack, @NotNull PathfinderMob entity) {
        if (isConverting(entity)) return InteractionResult.CONSUME;
        if (!entity.hasEffect(MobEffects.WEAKNESS)) return InteractionResult.CONSUME;
        if (!player.getAbilities().instabuild) {
            stack.shrink(1);
        }
        if (!entity.level().isClientSide()) {
            this.startConverting(player.getUUID(), entity.getRandom().nextInt(2400) + 2400, entity);
        }
        return InteractionResult.SUCCESS;
    }

    /**
     * @param entity the entity that extends this interface
     * @return if the entity is in progress of converting
     */
    default boolean isConverting(@NotNull PathfinderMob entity) {
        return entity.getEntityData().get(this.getConvertingDataParam());
    }

    /**
     * call in {@link Entity#defineSynchedData(net.minecraft.network.syncher.SynchedEntityData.Builder)}
     *
     * @param entity the entity that extends this interface
     */
    default void registerConvertingData(@NotNull SynchedEntityData.Builder builder) {
        builder.define(this.getConvertingDataParam(), false);
    }

    /**
     * called in {@link #interactWithCureItem(Player, ItemStack, PathfinderMob)} override to save values to attributes
     *
     * @param conversionStarterIn uuid of the player that started the curing process
     * @param conversionTimeIn    ticks the conversion should take
     * @param entity              the entity that extends this interface
     */
    default void startConverting(@Nullable UUID conversionStarterIn, int conversionTimeIn, @NotNull PathfinderMob entity) {
        entity.getEntityData().set(this.getConvertingDataParam(), true);
        entity.removeEffect(MobEffects.WEAKNESS);
        entity.level().broadcastEntityEvent(entity, (CURE_EVENT_ID));
    }


}

package de.teamlapen.vampirism.common.world.entity;

import de.teamlapen.vampirism.api.world.entity.convertible.IConvertedCreature;
import net.minecraft.world.Difficulty;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.NotNull;

public interface ConvertedCreature<T extends PathfinderMob> extends IConvertedCreature<T> {


    default void tickC() {
        if (this.asEntity().level().isClientSide() && this.asEntity().level().getDifficulty() == Difficulty.PEACEFUL) {
            this.asEntity().discard();
        }
    }

    default void readAdditionalSaveDataC(@NotNull ValueInput input) {
    }

    default void addAdditionalSaveDataC(@NotNull ValueOutput output) {
    }
}

package de.teamlapen.vampirism.common.world.entity;

import de.teamlapen.vampirism.common.core.ModSounds;
import de.teamlapen.vampirism.common.tags.ModBlockTags;
import de.teamlapen.vampirism.common.tags.ModDamageTypeTags;
import de.teamlapen.vampirism.common.util.Helper;
import de.teamlapen.vampirism.common.world.blockentity.MotherBlockEntity;
import de.teamlapen.vampirism.common.world.blockentity.VulnerableRemainsBlockEntity;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.Difficulty;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.damagesource.DamageTypes;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.ai.goal.LookAtPlayerGoal;
import net.minecraft.world.entity.ai.goal.RandomLookAroundGoal;
import net.minecraft.world.entity.ai.goal.target.NearestAttackableTargetGoal;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.EnumSet;
import java.util.Optional;

public class RemainsDefenderEntity extends Mob implements IRemainsEntity {

    protected static final EntityDataAccessor<Direction> DATA_ATTACH_FACE_ID = SynchedEntityData.defineId(RemainsDefenderEntity.class, EntityDataSerializers.DIRECTION);
    private static final EntityDataAccessor<Integer> DATA_LIGHT_TICKS_REMAINING = SynchedEntityData.defineId(RemainsDefenderEntity.class, EntityDataSerializers.INT);


    public static AttributeSupplier.Builder createAttributes() {
        return Mob.createMobAttributes().add(Attributes.MAX_HEALTH, 20.0D).add(Attributes.ARMOR, 15).add(Attributes.ATTACK_DAMAGE, 10).add(Attributes.ARMOR_TOUGHNESS, 6);
    }

    public RemainsDefenderEntity(EntityType<RemainsDefenderEntity> type, Level pLevel) {
        super(type, pLevel);
        this.xpReward = 5;
    }

    @Override
    protected void registerGoals() {
        this.goalSelector.addGoal(1, new LookAtPlayerGoal(this, Player.class, 10f, 0.5f, false));
        this.goalSelector.addGoal(2, new RemainsDefenderAttackGoal());
        this.goalSelector.addGoal(8, new RandomLookAroundGoal(this));
        this.targetSelector.addGoal(1, new RemainsDefenderAttackTargetGoal(this));

    }

    @Override
    protected Entity.@NotNull MovementEmission getMovementEmission() {
        return Entity.MovementEmission.NONE;
    }

    public @NotNull SoundSource getSoundSource() {
        return SoundSource.HOSTILE;
    }

    @Override
    public void tick() {
        super.tick();
        // remove in case the there is no remains block, but the entity was not removed or was added otherwise
        if (level().getGameTime() % 512 == 32 && getVehicle() == null && !level().getBlockState(blockPosition().relative(getAttachFace())).is(ModBlockTags.ACTIVE_REMAINS)) {
            this.remove(RemovalReason.KILLED);
        }
    }

    @Override
    public void aiStep() {
        super.aiStep();
        int i = this.getLightTicksRemaining();
        if (i > 0) {
            this.setLightTicksRemaining(i - 1);
        }
    }

    @Override
    public boolean isInvulnerableTo(@NotNull ServerLevel level, @NotNull DamageSource pSource) {
        return pSource.is(ModDamageTypeTags.MOTHER_RESISTANT_TO) || pSource.is(DamageTypes.IN_WALL) || pSource.is(DamageTypes.DROWN) || super.isInvulnerableTo(level, pSource);
    }

    @Nullable
    @Override
    protected SoundEvent getAmbientSound() {
        return ModSounds.REMAINS_DEFENDER_AMBIENT.get();
    }

    @Override
    protected SoundEvent getDeathSound() {
        return ModSounds.REMAINS_DEFENDER_DEATH.get();
    }

    @Nullable
    @Override
    protected SoundEvent getHurtSound(@NotNull DamageSource pDamageSource) {
        return ModSounds.REMAINS_DEFENDER_HURT.get();
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        super.defineSynchedData(builder);
        builder.define(DATA_ATTACH_FACE_ID, Direction.DOWN);
        builder.define(DATA_LIGHT_TICKS_REMAINING, 0);
    }

    @Override
    public void readAdditionalSaveData(@NotNull ValueInput input) {
        super.readAdditionalSaveData(input);
        this.setAttachFace(Direction.from3DDataValue(input.getByteOr("AttachFace", (byte) 0)));
        this.setLightTicksRemaining(input.getIntOr("LightTicks", 0));
    }

    @Override
    public void addAdditionalSaveData(@NotNull ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putByte("AttachFace", (byte) this.getAttachFace().get3DDataValue());
        output.putInt("LightTicks", this.getLightTicksRemaining());
    }

    @Override
    protected boolean canRide(@NotNull Entity pVehicle) {
        return pVehicle instanceof VulnerableRemainsDummyEntity;
    }

    @Override
    public void rideTick() {
        this.tick();
    }

    @Override
    public void move(@NotNull MoverType pType, @NotNull Vec3 pPos) {
    }

    @Override
    public boolean hurtServer(@NotNull ServerLevel level, @NotNull DamageSource pSource, float pAmount) {
        if (super.hurtServer(level, pSource, pAmount)) {
            this.getDummy().ifPresent(vehicle -> vehicle.childrenIsHurt(pSource, this.dead, getAttachFace()));
            return true;
        }
        return false;
    }

    @Override
    protected void actuallyHurt(@NotNull ServerLevel level, @NotNull DamageSource pDamageSource, float pDamageAmount) {
        super.actuallyHurt(level, pDamageSource, pDamageAmount);
        this.invulnerableTime *= 2;
    }

    @Override
    public @NotNull Vec3 getDeltaMovement() {
        return Vec3.ZERO;
    }

    @Override
    public void setDeltaMovement(@NotNull Vec3 pDeltaMovement) {
    }

    public void setAttachFace(Direction face) {
        this.entityData.set(DATA_ATTACH_FACE_ID, face);
    }

    public Direction getAttachFace() {
        return this.entityData.get(DATA_ATTACH_FACE_ID);
    }

    @Override
    public void onSyncedDataUpdated(@NotNull EntityDataAccessor<?> pKey) {
        if (DATA_ATTACH_FACE_ID.equals(pKey)) {
            this.setBoundingBox(this.makeBoundingBox());
            refreshDimensions();
        }
        super.onSyncedDataUpdated(pKey);
    }

    @Override
    public boolean canBeCollidedWith(@Nullable Entity entity) {
        return this.isAlive();
    }

    protected float getStandingEyeHeight(@NotNull Pose pPose, @NotNull EntityDimensions pSize) {
        return switch (getAttachFace()) {
            case UP -> 0.8f;
            case DOWN -> 0.2f;
            default -> 0.5f;
        };
    }

    @Override
    public void push(@NotNull Entity pEntity) {
    }

    @Override
    public boolean startRiding(Entity pEntity, boolean pForce, boolean sendGameEvent) {
        if (super.startRiding(pEntity, pForce, sendGameEvent)) {
            this.reapplyPosition();
            return true;
        }
        return false;
    }

    @Override
    protected @NotNull AABB makeBoundingBox(Vec3 pos) {
        Direction attachFace = getAttachFace().getOpposite();
        AABB box = new AABB(BlockPos.ZERO);
        return (switch (attachFace.getAxis()) {
            case X -> box.contract(0, 4d / 16, 4d / 16).contract(0, (-4d / 16), -(4d / 16));
            case Y -> box.contract(4d / 16, 0, 4d / 16).contract(-(4d / 16), 0, -(4d / 16));
            case Z -> box.contract(4d / 16, 4d / 16, 0).contract(-(4d / 16), -(4d / 16), 0);
        }).contract(attachFace.getStepX() * (12d / 16d), attachFace.getStepY() * (12d / 16d), attachFace.getStepZ() * (12d / 16d)).move(blockPosition());
    }

    public Optional<VulnerableRemainsDummyEntity> getDummy() {
        return Optional.ofNullable(this.getVehicle()).filter(VulnerableRemainsDummyEntity.class::isInstance).map(VulnerableRemainsDummyEntity.class::cast);
    }

    private void setLightTicksRemaining(int ticks) {
        this.entityData.set(DATA_LIGHT_TICKS_REMAINING, ticks);
    }

    public int getLightTicksRemaining() {
        return this.entityData.get(DATA_LIGHT_TICKS_REMAINING);
    }

    class RemainsDefenderAttackGoal extends Goal {
        private int attackTime;

        public RemainsDefenderAttackGoal() {
            this.setFlags(EnumSet.of(Goal.Flag.MOVE));
        }

        @Override
        public boolean canUse() {
            LivingEntity livingentity = RemainsDefenderEntity.this.getTarget();
            if (livingentity != null && livingentity.isAlive()) {
                return RemainsDefenderEntity.this.level().getDifficulty() != Difficulty.PEACEFUL;
            } else {
                return false;
            }
        }

        @Override
        public void start() {
            this.attackTime = 40;
        }

        @Override
        public boolean requiresUpdateEveryTick() {
            return true;
        }

        @Override
        public void tick() {
            if (RemainsDefenderEntity.this.level().getDifficulty() != Difficulty.PEACEFUL) {
                --this.attackTime;
                LivingEntity livingentity = RemainsDefenderEntity.this.getTarget();
                if (livingentity != null) {
                    RemainsDefenderEntity.this.getLookControl().setLookAt(livingentity, 180.0F, 180.0F);
                    double d0 = RemainsDefenderEntity.this.distanceToSqr(livingentity);
                    if (d0 < 400) {
                        if (this.attackTime <= 0) {
                            this.attackTime = 20 + RemainsDefenderEntity.this.random.nextInt(10) * 20 / 2;
                            Vec3 position = RemainsDefenderEntity.this.position();
                            Vec3 direction = RemainsDefenderEntity.this.getViewVector(1.0f);
                            var projectile = new DarkBloodProjectileEntity(RemainsDefenderEntity.this.level(), position.x(), position.y(), position.z(), direction);
                            projectile.setOwner(RemainsDefenderEntity.this);
                            projectile.setDamage((float) RemainsDefenderEntity.this.getAttributeValue(Attributes.ATTACK_DAMAGE), 0);
                            projectile.excludeShooter();
                            RemainsDefenderEntity.this.level().addFreshEntity(projectile);
                            RemainsDefenderEntity.this.setLightTicksRemaining(40);
                        }
                    } else {
                        RemainsDefenderEntity.this.setTarget(null);
                    }

                    super.tick();
                }
            }
        }
    }

    static class RemainsDefenderAttackTargetGoal extends NearestAttackableTargetGoal<LivingEntity> {

        public RemainsDefenderAttackTargetGoal(RemainsDefenderEntity entity) {
            super(entity, LivingEntity.class, 10, true, false, (target, level) -> {
                if (target instanceof ServerPlayer player && entity.getDummy().flatMap(VulnerableRemainsDummyEntity::getTile).flatMap(VulnerableRemainsBlockEntity::getMother).map(MotherBlockEntity::involvedPlayers).stream().anyMatch(s -> s.contains(player))) {
                    return true;
                } else {
                    return !(target instanceof IRemainsEntity) && !Helper.isVampire(target);
                }
            });
        }
    }

    @Override
    protected void reapplyPosition() {
        if (this.getVehicle() != null) {
            Direction attachFace = getAttachFace();
            this.setPos(Vec3.atBottomCenterOf(this.getVehicle().blockPosition().above()).subtract(attachFace.getStepX(), attachFace.getStepY(), attachFace.getStepZ()));
        } else {
            super.reapplyPosition();
        }
    }
}

package de.teamlapen.vampirism.common.world.entity;

import de.teamlapen.faction.api.world.entities.IEntityLeader;
import de.teamlapen.vampirism.common.core.ModBlocks;
import de.teamlapen.vampirism.common.core.ModEntities;
import de.teamlapen.vampirism.common.core.ModSounds;
import de.teamlapen.vampirism.common.tags.ModDamageTypeTags;
import de.teamlapen.vampirism.common.world.blockentity.VulnerableRemainsBlockEntity;
import it.unimi.dsi.fastutil.objects.Object2IntMap;
import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.Nullable;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;

public class VulnerableRemainsDummyEntity extends LivingEntity implements IEntityLeader, IRemainsEntity {

    @Nullable
    private BlockPos ownerPos = null;
    private final Object2IntMap<Direction> delayRespawn = new Object2IntOpenHashMap<>();

    public VulnerableRemainsDummyEntity(EntityType<VulnerableRemainsDummyEntity> type, Level pLevel) {
        super(type, pLevel);
    }

    public static AttributeSupplier.Builder createAttributes() {
        return LivingEntity.createLivingAttributes();
    }

    @Override
    public float getHealth() {
        return getTile().map(VulnerableRemainsBlockEntity::getHealth).orElse(1);
    }

    @Override
    public boolean canBeCollidedWith(@Nullable Entity entity) {
        return this.isAlive();
    }

    @Override
    public Vec3 getDeltaMovement() {
        return Vec3.ZERO;
    }

    @Override
    public void setDeltaMovement(Vec3 pMotion) {
    }

    @Override
    protected void actuallyHurt(ServerLevel level, DamageSource pDamageSource, float pDamageAmount) {
        getTile().ifPresent(vr -> {
            vr.onDamageDealt(pDamageSource, pDamageAmount);
        });
        if (pDamageSource.getEntity() instanceof LivingEntity attacker) {
            attacker.hurtServer(level, damageSources().thorns(this), 3);
        }
    }

    public void childrenIsHurt(DamageSource damageSource, boolean killed, Direction direction) {
        getTile().ifPresent(vr -> {
            vr.onDamageDealt(damageSource, 0);
        });
        if (killed) {
            this.delayRespawn.put(direction, 20 * 5);
        }
    }

    @Override
    public boolean isInvulnerableTo(ServerLevel level, DamageSource pSource) {
        return this.isRemoved() || pSource.is(ModDamageTypeTags.MOTHER_RESISTANT_TO);
    }

    @Override
    public ItemStack getItemBySlot(EquipmentSlot pSlot) {
        return ItemStack.EMPTY;
    }

    @Override
    public void setItemSlot(EquipmentSlot pSlot, ItemStack pStack) {

    }

    @Override
    public boolean isPickable() {
        return true; //This ensures the entity can be targeted by client which is required to be able to hit it
    }

    @Override
    public HumanoidArm getMainArm() {
        return HumanoidArm.LEFT;
    }


    @Override
    public void push(Entity pEntity) {
    }

    public void setOwnerLocation(BlockPos pos) {
        this.ownerPos = pos;
    }

    @Override
    public void tick() {
        this.noPhysics = true;
        super.tick();
        this.noPhysics = false;
        if (!this.level().isClientSide()) {
            BlockState block = this.level().getBlockState(ownerPos);
            if (this.ownerPos == null || !block.is(ModBlocks.ACTIVE_VULNERABLE_REMAINS.get()) || block.is(ModBlocks.INCAPACITATED_VULNERABLE_REMAINS.get())) {
                if (block.is(ModBlocks.INCAPACITATED_VULNERABLE_REMAINS.get())) {
                    this.getPassengers().forEach(s -> s.setRemoved(RemovalReason.DISCARDED));
                }
                this.remove(RemovalReason.DISCARDED);
            } else if (level().getGameTime() % 400 == 16) {
                spawnDefender();
            }
        }
    }

    public void spawnDefender() {
        BlockPos pos = this.ownerPos;

        List<Direction> directionStream = Arrays.stream(Direction.values()).filter(direction -> this.delayRespawn.getOrDefault(direction, 0) <= 0).filter(l -> {
            var block = this.level().getBlockState(pos.relative(l)).canBeReplaced();
            return block && !hasDefender(l);
        }).toList();
        if (!directionStream.isEmpty()) {
            spawnDefender(directionStream.get(this.random.nextInt(directionStream.size())));
        }
    }

    public void spawnDefenders() {
        this.delayRespawn.clear();
        BlockPos pos = this.ownerPos;
        Arrays.stream(Direction.values()).filter(l -> {
            var block = this.level().getBlockState(pos.relative(l)).canBeReplaced();
            return block && !hasDefender(l);
        }).forEach(this::spawnDefender);
    }

    private boolean hasDefender(Direction direction) {
        return getPassengers().stream().anyMatch(entity -> entity instanceof RemainsDefenderEntity defender && defender.getAttachFace().getOpposite() == direction);
    }

    public void spawnDefender(Direction direction) {
        RemainsDefenderEntity defender = ModEntities.REMAINS_DEFENDER.get().create(this.level(), EntitySpawnReason.MOB_SUMMONED);
        getTile().map(BlockEntity::getBlockPos).ifPresent(pos -> {
            defender.setPos(Vec3.atBottomCenterOf(pos.relative(direction)));
            defender.setAttachFace(direction.getOpposite());
            level().addFreshEntity(defender);
            defender.startRiding(this);
            defender.setYRot(0);
            defender.yHeadRot = getYRot();
            defender.setOldPosAndRot();
        });
    }

    @Override
    protected boolean canAddPassenger(Entity pPassenger) {
        return pPassenger instanceof RemainsDefenderEntity && getPassengers().size() < 6;
    }

    public Optional<VulnerableRemainsBlockEntity> getTile() {
        if (ownerPos != null && this.level().isLoaded(ownerPos)) { //Check if block is still loaded. Occasionally, this is called during chunk unload. #1490) {
            if (this.level().getBlockEntity(ownerPos) instanceof VulnerableRemainsBlockEntity vr) {
                return Optional.of(vr);
            }
        }
        return Optional.empty();
    }

    @Override
    public void addAdditionalSaveData(ValueOutput output) {
        output.putIntArray("ownerPos", new int[]{this.ownerPos.getX(), this.ownerPos.getY(), this.ownerPos.getZ()});
    }

    @Override
    protected Entity.MovementEmission getMovementEmission() {
        return Entity.MovementEmission.NONE;
    }

    @Override
    public void readAdditionalSaveData(ValueInput input) {
        input.getIntArray("ownerPos").ifPresentOrElse(pos -> this.ownerPos = new BlockPos(pos[0], pos[1], pos[2]), this::discard);
    }

    private int followerCount = 0;

    @Override
    public void decreaseFollowerCount() {
        followerCount--;
    }

    @Override
    public int getFollowingCount() {
        return this.followerCount;
    }

    @Override
    public int getMaxFollowerCount() {
        return isAlive() ? Integer.MAX_VALUE : 0;
    }

    @Override
    public LivingEntity asEntity() {
        return this;
    }

    @Override
    public boolean increaseFollowerCount() {
        followerCount++;
        return true;
    }

    @Nullable
    @Override
    public SoundEvent getDeathSound() {
        return ModSounds.REMAINS_DEATH.get();
    }

    @Override
    public SoundSource getSoundSource() {
        return SoundSource.HOSTILE;
    }

    @Nullable
    @Override
    protected SoundEvent getHurtSound(DamageSource pDamageSource) {
        return ModSounds.REMAINS_HURT.get();
    }
}

package de.teamlapen.vampirism.common.world.entity.converted;

